    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    # Find a non-background horizontal run reaching the right edge, preceded
    # immediately by a background cell. Prefer the longest such run.
    best = None
    for r, row in enumerate(grid):
        color = row[-1]
        if color == bg:
            continue
        start = w - 1
        while start > 0 and row[start - 1] == color:
            start -= 1
        if start > 0 and row[start - 1] == bg:
            length = w - start
            if best is None or length > best[0]:
                best = (length, r, start)
    if best:
